cypress_script:
describe('Progress Bar Functionality', () => {
  it('should start the progress bar', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    // Assuming the progress bar starts filling, we check if the button is still present.
    cy.get('#startStopButton').should('be.visible');
  });

  it('should not change URL when clicking the start/stop button', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.url().should('eq', 'https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.get('#startStopButton').click();
    cy.url().should('eq', 'https://demoqa.com/progress-bar');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Progress Bar Functionality', () => {
  test('should start the progress bar', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    // Assuming the progress bar starts filling, we check if the button is still present.
    const button = await page.$('#startStopButton');
    expect(button).toBeTruthy();
  });

  test('should not change URL when clicking the start/stop button', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await expect(page).toHaveURL('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    await page.click('#startStopButton');
    await expect(page).toHaveURL('https://demoqa.com/progress-bar');
  });
});
